import {test,expect} from 'bun:test';
import {mkdtempSync,writeFileSync,readFileSync,rmSync,readdirSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {createRulesHolder,parseRules,loadRules,sourceEtagOf,type Rule} from '../../src/rules/rules.js';
import {writeRulesFile} from '../../src/rules/write-rules.js';
import {createRuleRuntime,type RuntimeUpdate} from '../../src/control-panel/rule-runtime.js';
import {reconcileNow,scopedHerd} from '../../src/daemon/loop.js';
import type {Herd,SpawnSpec} from '../../src/agents/herd.js';
import type {RemoteRule} from '../../src/control-panel/remote-rules.js';
import {createAdmissionController} from '../../src/agents/admission.js';
const source={serverId:'00000000-0000-4000-8000-000000000001',authorizationId:'00000000-0000-4000-8000-000000000002'};
const doc={rules:[{id:'worker',resourceProvider:'jira-work',query:'project = FIXTURE',brief:'Original instructions\n',enabled:true,execution:'swarm',role:'worker',relationships:{childRule:'parked'}},{id:'parked',resourceProvider:'jira-work',query:'project = PARKED',brief:'Never start',enabled:false,role:'worker'}]};
const key=(suffix='1')=>'jira-work:worker:FIXTURE-'+suffix;
const spec=(id:string):SpawnSpec=>({key:id,issuetype:'Task',summary:'Disposable fake worker',parent:null});
function rows(document:unknown=doc):RemoteRule[]{return parseRules(document).map(definition=>({id:`remote:${source.serverId}:${source.authorizationId}:${definition.id}`,source:'remote',...source,sourceRuleId:definition.id,definition,executionState:'staged'}));}
function fixture(){const directory=mkdtempSync(join(tmpdir(),'butchr-rule-runtime-')),path=join(directory,'rules.json'),env={BUTCHR_RULES_FILE:path};const original=JSON.stringify(doc,null,2)+'\n';writeFileSync(path,original,{mode:0o600});const holder=createRulesHolder(parseRules(doc),sourceEtagOf(original));
 const local={holder,readText:()=>readFileSync(path,'utf8'),writeText:(text:string,ifMatch:string)=>writeRulesFile(text,env,undefined,{ifMatch}),reload:()=>{const next=loadRules(env);holder.setRules(next.rules);holder.setSourceEtag(sourceEtagOf(next.text));return {ok:true};}};
 let runtime=createRuleRuntime(directory,local),control={enabled:true,disabledRules:[] as string[]},remote=rows();const update=(change:Partial<RuntimeUpdate>={})=>runtime.update({connected:true,rules:remote,revision:'a'.repeat(64),source,control,...change});
 const activate=()=>{runtime.recordFullCensus(runtime.observedWorkerIds(),true);const p=runtime.plan();return runtime.activate({localDigest:p.localDigest!,remoteDigest:p.remoteDigest!,confirm:true});};
 return {directory,path,holder,local,original,get runtime(){return runtime},get control(){return control},set control(v){control=v},get remote(){return remote},set remote(v){remote=v},update,activate,restart:()=>{runtime=createRuleRuntime(directory,local);return runtime;},close:()=>rmSync(directory,{recursive:true,force:true})};}
function herd(initial:string[]=[]){const running=new Set(initial),actions:string[]=[];let stale:string[]=[],frozen=new Set<string>();const h:Herd={ruleCensus:async()=>({ids:[...running],complete:true}),runningIssues:async()=>[...running],staleIssues:async()=>stale.map(issue=>({issue,reason:'fixture stale',observedArgv:[],resumable:true})),spawn:async s=>{actions.push('spawn:'+s.key);running.add(s.key)},stop:async id=>{actions.push('stop:'+id);running.delete(id)},resumeInPlace:async s=>{actions.push('resume:'+s.key);return 'unresumable'},paneFor:async()=>null,nudge:async()=>{actions.push('nudge');return {delivered:true}},frozen:async ids=>new Set(ids.filter(id=>frozen.has(id)))};return {h,running,actions,setStale:(v:string[])=>stale=v,setFrozen:(v:string[])=>frozen=new Set(v)};}
test('default local behavior, explicit equivalent activation and stable scoped reconciler preserve existing worker identity',async()=>{const f=fixture(),workers=herd([key()]);try{workers.h.ruleRuntime=()=>f.runtime.policy;const scoped=scopedHerd(workers.h,id=>id.startsWith('jira-work:'));const desired=new Map([[key(),spec(key())]]);await reconcileNow(scoped,desired);f.update();f.activate();await reconcileNow(scoped,desired);expect(workers.actions).toEqual([]);expect(f.runtime.summary().authority).toBe('remote');expect(f.runtime.getRules().map(r=>r.id)).toEqual(['worker','parked']);expect(f.runtime.ruleForAgent(key())!.role).toBe('worker');expect(f.runtime.getRules()[1]!.enabled).toBe(false);}finally{f.close();}});
test('master-off, local disables, disconnect and deletion cannot kill/resume admitted agents or spawn replacements',async()=>{const f=fixture(),workers=herd([key()]);try{workers.h.ruleRuntime=()=>f.runtime.policy;const desired=new Map([[key(),spec(key())]]);await reconcileNow(workers.h,desired);f.update();f.activate();workers.setStale([key()]);
 for(const change of [{control:{enabled:false,disabledRules:[]}},{control:{enabled:true,disabledRules:[f.remote[0]!.id]}},{connected:false,rules:[],revision:null},{connected:true,rules:[],revision:'b'.repeat(64)}] as Partial<RuntimeUpdate>[]){f.update(change);await reconcileNow(workers.h,new Map([[key(),spec(key())],[key('2'),spec(key('2'))]]));expect(workers.actions).toEqual([]);expect(f.runtime.policy.canNotify(key(),0,f.runtime.policy.generation())).toBe(false);}
 }finally{f.close();}});
test('running policy snapshots survive role/model churn and real durable restart while new workers use current rules',async()=>{const f=fixture(),workers=herd();try{f.update();f.activate();workers.h.ruleRuntime=()=>f.runtime.policy;await reconcileNow(workers.h,new Map([[key(),spec(key())]]));expect(workers.actions).toEqual(['spawn:'+key()]);f.remote=rows({rules:[{...doc.rules[0],role:'sentinel',brief:'Changed',agentPreferences:[{harness:'codex',model:'gpt-5.6-sol'}]},doc.rules[1]]});f.update();workers.setStale([key()]);await reconcileNow(workers.h,new Map([[key(),spec(key())]]));expect(workers.actions).toEqual(['spawn:'+key()]);expect(f.runtime.ruleForAgent(key())!.role).toBe('worker');f.restart();workers.h.ruleRuntime=()=>f.runtime.policy;expect(f.runtime.getRules()[0]!.enabled).toBe(false);expect(f.runtime.getInitializationRules()[0]!.enabled).toBe(true);f.update();await reconcileNow(workers.h,new Map([[key(),spec(key())],[key('2'),spec(key('2'))]]));expect(workers.actions).toEqual(['spawn:'+key(),'spawn:'+key('2')]);expect(f.runtime.ruleForAgent(key())!.brief).toBe('Original instructions\n');expect(f.runtime.ruleForAgent(key('2'))!.role).toBe('sentinel');}finally{f.close();}});
test('late admission is fenced and reservations released when an override changes during the real admission hook',async()=>{const f=fixture(),workers=herd();try{f.update();f.activate();workers.h.ruleRuntime=()=>f.runtime.policy;const released:string[]=[];let admitted:string[]=[];await reconcileNow(workers.h,new Map([[key(),spec(key())]]),{admission:async ids=>{f.update({control:{enabled:false,disabledRules:[]}});return [...ids]},releaseAdmission:async ids=>{released.push(...ids)},onAdmitted:ids=>{admitted=[...ids]}});expect(workers.actions).toEqual([]);expect(released).toContain(key());expect(admitted).toEqual([]);}finally{f.close();}});
test('actual admission capacity and freeze constraints remain in force after remote activation',async()=>{const f=fixture(),workers=herd();try{f.update();f.activate();workers.h.ruleRuntime=()=>f.runtime.policy;const admission=createAdmissionController({cap:1,residency:async()=>["existing-fixture-resident"],log:()=>{}});await reconcileNow(workers.h,new Map([[key(),spec(key())]]),{admission:(ids,stopping)=>admission.admit(ids,stopping)});expect(workers.actions).toEqual([]);workers.setFrozen([key()]);await reconcileNow(workers.h,new Map([[key(),spec(key())]]));expect(workers.actions).toEqual([]);}finally{f.close();}});
test('recoverable deactivation uses backups, survives restart and rollback restores exact local bytes without duplicate spawn',async()=>{const f=fixture(),workers=herd([key()]);try{workers.h.ruleRuntime=()=>f.runtime.policy;await reconcileNow(workers.h,new Map([[key(),spec(key())]]));f.update();f.activate();const p=f.runtime.plan(),result=f.runtime.deactivateLocal({localDigest:p.localDigest!,remoteDigest:p.remoteDigest!,confirm:true});expect(result.backupId).toBeTruthy();expect(JSON.parse(readFileSync(f.path,'utf8')).rules).toEqual([]);expect(readdirSync(f.directory).some(n=>n.startsWith('rules.json.bak'))).toBe(true);f.restart();workers.h.ruleRuntime=()=>f.runtime.policy;f.update();await reconcileNow(workers.h,new Map([[key(),spec(key())]]));expect(workers.actions).toEqual([]);f.runtime.rollback(true);expect(readFileSync(f.path,'utf8')).toBe(f.original);expect(f.runtime.summary().authority).toBe('local');await reconcileNow(workers.h,new Map([[key(),spec(key())]]));expect(workers.actions).toEqual([]);}finally{f.close();}});
test('inequivalence and concurrent local edits prevent activation/deactivation/rollback without overwriting data',()=>{const f=fixture();try{f.update();f.remote=rows({rules:[{...doc.rules[0],query:'project = CHANGED'},doc.rules[1]]});f.update();expect(()=>f.activate()).toThrow();f.remote=rows();f.update();f.activate();const p=f.runtime.plan();f.runtime.deactivateLocal({localDigest:p.localDigest!,remoteDigest:p.remoteDigest!,confirm:true});const changed='{ "rules": [], "ownerDraft": true }';writeFileSync(f.path,changed);expect(()=>f.runtime.rollback(true)).toThrow('changed');expect(readFileSync(f.path,'utf8')).toBe(changed);}finally{f.close();}});
test('a launch that creates a worker then throws retains its admitted policy across later churn',async()=>{const f=fixture(),workers=herd();try{f.update();f.activate();workers.h.ruleRuntime=()=>f.runtime.policy;workers.h.spawn=async s=>{workers.running.add(s.key);throw Error('fixture post-create failure')};await reconcileNow(workers.h,new Map([[key(),spec(key())]]));f.remote=rows({rules:[{...doc.rules[0],role:'sentinel',lizardMode:true},doc.rules[1]]});f.update();await reconcileNow(workers.h,new Map([[key(),spec(key())]]));expect(f.runtime.ruleForAgent(key())!.role).toBe('worker');expect(f.runtime.ruleForAgent(key())!.lizardMode).not.toBe(true);}finally{f.close();}});
test('explicit connection removal synchronously fences an already active runtime',async()=>{const f=fixture();const {createControlPanelClient}=await import('../../src/control-panel/client.js');const fake=(async(_input:unknown)=>{throw Error('fixture offline')}) as unknown as typeof fetch;const client=createControlPanelClient(f.directory,fake);try{client.configure({serverUrl:'http://127.0.0.1:1',key:'bsv1_'+'M'.repeat(43)});await Bun.sleep(5);const runtime=client.attachRuleRuntime(f.local);runtime.update({connected:true,rules:rows(),revision:'a'.repeat(64),source,control:{enabled:true,disabledRules:[]}});runtime.recordFullCensus([],true);const p=runtime.plan();runtime.activate({localDigest:p.localDigest!,remoteDigest:p.remoteDigest!,confirm:true});expect(runtime.policy.canAdmit(key(),runtime.policy.generation())).toBe(true);client.configure({disconnect:true});expect(runtime.policy.canAdmit(key(),runtime.policy.generation())).toBe(false);expect(runtime.summary().connected).toBe(false);}finally{client.stop();f.close();}});
test('activation requires a complete census and binds preexisting workers before newer remote policy arrives',async()=>{const f=fixture();try{f.update();const p=f.runtime.plan();expect(()=>f.runtime.activate({localDigest:p.localDigest!,remoteDigest:p.remoteDigest!,confirm:true})).toThrow('census');f.runtime.recordFullCensus([key()],true);f.runtime.activate({localDigest:p.localDigest!,remoteDigest:p.remoteDigest!,confirm:true});f.remote=rows({rules:[{...doc.rules[0],role:'sentinel',lizardMode:true,agentPreferences:[{harness:'codex',model:'new-remote-model'}]},doc.rules[1]]});f.update();expect(f.runtime.ruleForAgent(key())!.role).toBe('worker');expect(f.runtime.ruleForAgent(key())!.lizardMode).not.toBe(true);}finally{f.close();}});
test('previously unseen workers stay explicitly unresolved before stale/model/permission checks',async()=>{const f=fixture(),workers=herd([key('99')]);try{f.update();f.activate();f.remote=rows({rules:[{...doc.rules[0],role:'sentinel',lizardMode:true},doc.rules[1]]});f.update();workers.h.ruleRuntime=()=>f.runtime.policy;let checked=false;workers.h.staleIssues=async()=>{checked=true;expect(f.runtime.ruleForAgent(key('99'))).toBeUndefined();return [{issue:key('99'),reason:'fixture model mismatch',observedArgv:[],resumable:true}]};await reconcileNow(workers.h,new Map([[key('99'),spec(key('99'))]]));expect(checked).toBe(true);expect(f.runtime.ruleForAdmission(key('99'))).toBeUndefined();expect(f.runtime.retainedRules().find(r=>r.id===key('99'))).toBeUndefined();expect(f.runtime.summary().unresolvedAgents).toBe(1);expect(workers.actions).toEqual([]);}finally{f.close();}});
test('post-spawn callback failure does not erase a successfully launched worker admission snapshot',async()=>{const f=fixture(),workers=herd();try{f.update();f.activate();workers.h.ruleRuntime=()=>f.runtime.policy;workers.h.lastFreshSpawnResumed=()=>true;await reconcileNow(workers.h,new Map([[key(),spec(key())]]),{onRespawnResumed:async()=>{throw Error('fixture notification callback')}});f.remote=rows({rules:[{...doc.rules[0],lizardMode:true,role:'sentinel'},doc.rules[1]]});f.update();expect(f.runtime.ruleForAgent(key())!.role).toBe('worker');expect(f.runtime.ruleForAgent(key())!.lizardMode).not.toBe(true);expect(workers.actions).toEqual(['spawn:'+key()]);}finally{f.close();}});
async function until(check:()=>boolean,timeout=2000){const end=Date.now()+timeout;while(!check()){if(Date.now()>end)throw Error('Fixture condition timed out');await Bun.sleep(10);}}
async function notificationFixture(run:(f:ReturnType<typeof fixture>,state:{version:number;searches:number;notified:number[];midSearch?:()=>void})=>Promise<void>){const {runResourceLoop}=await import('../../src/daemon/loop.js');const f=fixture(),workers=herd([key()]),state:{version:number;searches:number;notified:number[];midSearch?:()=>void}={version:1,searches:0,notified:[]};f.update();f.runtime.recordFullCensus([key()],true);const p=f.runtime.plan();f.runtime.activate({localDigest:p.localDigest!,remoteDigest:p.remoteDigest!,confirm:true});workers.h.ruleRuntime=()=>f.runtime.policy;
 const stop=runResourceLoop<{id:string;version:number}>({discovery:{idOf:r=>r.id,search:async()=>{state.searches++;const result=[{id:key(),version:state.version}];const action=state.midSearch;delete state.midSearch;action?.();return result;}},activation:{verdictFor:()=> 'active'},spawnConfig:{specFor:r=>spec(r.id)},eventRules:{poll:async(prev,next)=>({changedPrimary:next.primary.filter(n=>prev.primary.some(o=>o.id===n.id&&o.version!==n.version)).map(r=>r.id),changedRelated:[],decide:async()=>({deliver:true})})}},{herd:workers.h,ownsId:()=>true,ruleProvider:'jira-work',intervalMs:10,notify:async()=>{state.notified.push(state.version)}});
 try{await until(()=>state.searches>=3);await run(f,state);}finally{stop();await Bun.sleep(20);f.close();}}
test('real resource loop preserves committed observation baseline across disconnect and delivers the changed resource once',async()=>notificationFixture(async(f,state)=>{f.update({connected:false,rules:[],revision:null});const searches=state.searches;state.version=2;await Bun.sleep(45);expect(state.searches).toBe(searches);expect(state.notified).toEqual([]);f.update();await until(()=>state.notified.length===1);await Bun.sleep(45);expect(state.notified).toEqual([2]);}));
test('brief-only/same-rule updates mid-search do not invalidate or lose an observation',async()=>notificationFixture(async(f,state)=>{const generation=f.runtime.policy.generation();state.version=2;state.midSearch=()=>f.update({revision:'b'.repeat(64)});await until(()=>state.notified.length===1);await Bun.sleep(35);expect(f.runtime.policy.generation()).toBe(generation);expect(state.notified).toEqual([2]);}));
test('control invalidation mid-search retains the resource change until a fresh reconnect poll',async()=>notificationFixture(async(f,state)=>{state.version=2;state.midSearch=()=>f.update({connected:false,rules:[],revision:null});await until(()=>f.runtime.summary().connected===false);await Bun.sleep(30);expect(state.notified).toEqual([]);f.update();await until(()=>state.notified.length===1);await Bun.sleep(30);expect(state.notified).toEqual([2]);}));
test('incomplete census never prunes admitted policy or enables admission/lifecycle',async()=>{const f=fixture(),workers=herd([key()]);try{workers.h.ruleRuntime=()=>f.runtime.policy;await reconcileNow(workers.h,new Map([[key(),spec(key())]]));f.update();f.activate();f.runtime.recordFullCensus([],false);expect(f.runtime.summary().phase).toBe('inventory-uncertain');expect(f.runtime.ruleForAgent(key())!.role).toBe('worker');expect(f.runtime.policy.canAdmit(key('2'),f.runtime.policy.generation())).toBe(false);expect(f.runtime.policy.protectStop(key(),f.runtime.policy.generation())).toBe(true);f.runtime.recordFullCensus([key()],true);expect(f.runtime.summary().phase).toBe('active');}finally{f.close();}});
test('directory fsync failure after authority rename fails closed and recovers only from durable state',()=>{const f=fixture();try{const runtime=createRuleRuntime(f.directory,f.local,()=>{throw Error('fixture sync failure')});runtime.update({connected:true,rules:rows(),revision:'a'.repeat(64),source,control:{enabled:true,disabledRules:[]}});runtime.recordFullCensus([],true);const p=runtime.plan();expect(()=>runtime.activate({localDigest:p.localDigest!,remoteDigest:p.remoteDigest!,confirm:true})).toThrow('sync failure');expect(runtime.summary().phase).toBe('blocked');expect(runtime.policy.canAdmit(key(),runtime.policy.generation())).toBe(false);const recovered=f.restart();f.update();recovered.recordFullCensus([],true);expect(recovered.summary().authority).toBe('remote');expect(recovered.summary().phase).toBe('active');}finally{f.close();}});
test('failed local deactivation write preserves active authority and exact-byte recoverable baseline',()=>{const f=fixture();try{const runtime=createRuleRuntime(f.directory,{...f.local,writeText:()=>{throw Error('fixture local write');}});runtime.update({connected:true,rules:rows(),revision:'a'.repeat(64),source,control:{enabled:true,disabledRules:[]}});runtime.recordFullCensus([],true);let p=runtime.plan();runtime.activate({localDigest:p.localDigest!,remoteDigest:p.remoteDigest!,confirm:true});p=runtime.plan();expect(()=>runtime.deactivateLocal({localDigest:p.localDigest!,remoteDigest:p.remoteDigest!,confirm:true})).toThrow('local write');expect(readFileSync(f.path,'utf8')).toBe(f.original);runtime.rollback(true);expect(runtime.summary().authority).toBe('local');}finally{f.close();}});
test('an additive query change admits a newly eligible resource at once, adopts the query immediately and leaves the retained worker untouched',async()=>{const f=fixture(),workers=herd([key()]);try{workers.h.ruleRuntime=()=>f.runtime.policy;await reconcileNow(workers.h,new Map([[key(),spec(key())]]));f.update();f.activate();
 f.remote=rows({rules:[{...doc.rules[0],query:'project = FIXTURE OR project = FUTURE'},doc.rules[1]]});f.update();
 expect(f.runtime.summary().discoveryChangesDeferred).toBe(false);expect(f.runtime.getRules()[0]!.query).toBe('project = FIXTURE OR project = FUTURE');
 await reconcileNow(workers.h,new Map([[key(),spec(key())],[key('2'),spec(key('2'))]]));expect(workers.actions).toEqual(['spawn:'+key('2')]);
 expect(f.runtime.ruleForAgent(key())!.role).toBe('worker');
 }finally{f.close();}});
test('production discovery itself reads the live query every poll: a new-only match admits, an old-only match retires, and a replacement does both while an unrelated resident stays',async()=>{
 const {runResourceLoop}=await import('../../src/daemon/loop.js');
 const f=fixture(),workers=herd([key()]),universe=[{id:key(),project:'FIXTURE'},{id:key('2'),project:'FUTURE'},{id:key('3'),project:'UNRELATED'}];
 const matches=(query:string,project:string)=>query.split(' OR ').some(clause=>clause.trim()===`project = ${project}`);
 f.update();f.runtime.recordFullCensus([key()],true);const p=f.runtime.plan();f.runtime.activate({localDigest:p.localDigest!,remoteDigest:p.remoteDigest!,confirm:true});
 workers.h.ruleRuntime=()=>f.runtime.policy;
 let searches=0;
 const stop=runResourceLoop<{id:string;project:string}>({discovery:{idOf:r=>r.id,search:async()=>{searches++;return universe.filter(r=>matches(f.runtime.getRules().find(d=>d.id==='worker')!.query,r.project));}},activation:{verdictFor:()=>'active'},spawnConfig:{specFor:r=>spec(r.id)},eventRules:{poll:async()=>({changedPrimary:[],changedRelated:[],decide:async()=>({deliver:false})})}},{herd:workers.h,ownsId:()=>true,ruleProvider:'jira-work',intervalMs:10,notify:async()=>{}});
 try{
  await until(()=>searches>=2);expect(workers.actions).toEqual([]);expect(workers.running.has(key())).toBe(true);
  f.remote=rows({rules:[{...doc.rules[0],query:'project = FIXTURE OR project = FUTURE'},doc.rules[1]]});f.update();
  await until(()=>workers.running.has(key('2')));
  expect(workers.running.has(key())).toBe(true);expect(workers.running.has(key('3'))).toBe(false);
  f.remote=rows({rules:[{...doc.rules[0],query:'project = FUTURE OR project = UNRELATED'},doc.rules[1]]});f.update();
  await until(()=>!workers.running.has(key())&&workers.running.has(key('3')));
  expect(workers.running.has(key('2'))).toBe(true);
 }finally{stop();await Bun.sleep(20);f.close();}
});
test('a retained worker whose rule also picks up a behavior-field edit, not just query, does not fence an otherwise newly eligible resource under the same rule',async()=>{const f=fixture(),workers=herd([key()]);try{
 workers.h.ruleRuntime=()=>f.runtime.policy;await reconcileNow(workers.h,new Map([[key(),spec(key())]]));f.update();f.activate();
 f.remote=rows({rules:[{...doc.rules[0],query:'project = FIXTURE OR project = FUTURE',maxLinkedItems:7},doc.rules[1]]});f.update();
 expect(f.runtime.summary().discoveryChangesDeferred).toBe(true);expect(f.runtime.getRules()[0]!.maxLinkedItems).not.toBe(7);
 expect(f.runtime.policy.canAdmit(key('2'),f.runtime.policy.generation())).toBe(true);
 await reconcileNow(workers.h,new Map([[key(),spec(key())],[key('2'),spec(key('2'))]]));expect(workers.actions).toEqual(['spawn:'+key('2')]);
 expect(workers.running.has(key())).toBe(true);
 const deferred=f.runtime.summary().deferredRules.find(d=>d.id==='worker')!;expect(deferred.admissionBlocked).toBe(false);expect(deferred.differingFields).toContain('maxLinkedItems');expect(deferred.differingFields).not.toContain('query');expect(deferred.holdingWorkers).toContain(key());
 }finally{f.close();}});
